/** Target ownership, not a second runtime API registry. Current facts live in the matrix. */
export type Family = "Domain" | "Contribution" | "Service" | "Schema" | "Contract" | "Boundary";
export type Unit = {
  id: string;
  family: Family;
  owner: string;
  title: string;
  refs: string[];
  catalog: string[];
  operations: string;
  agent: string;
  plugin: string;
  limits: string;
  acceptance: string;
};
const ids = (text: string): string[] =>
  text
    .split(/\s+/)
    .filter(Boolean)
    .flatMap((token) => {
      const range = /^(\D+)(\d+)-(\d+)$/.exec(token);
      return range
        ? Array.from(
            { length: Number(range[3]) - Number(range[2]) + 1 },
            (_, i) => `${range[1]}${String(Number(range[2]) + i).padStart(2, "0")}`,
          )
        : [token];
    });
function unit(
  id: string,
  family: Family,
  owner: string,
  title: string,
  refs: string,
  catalog: string,
  operations: string,
  agent: string,
  plugin: string,
  limits: string,
  acceptance: string,
): Unit {
  return {
    id,
    family,
    owner,
    title,
    refs: ids(refs),
    catalog: catalog.split(" ").filter(Boolean),
    operations,
    agent,
    plugin,
    limits,
    acceptance,
  };
}
